export const B3_RVR: Record<string, string> = {
  "hs-jhn14-16": "Y yo rogar\u{e9} al Padre, y os dar\u{e1} otro Consolador, para que est\u{e9} con vosotros para siempre:",
  "hs-jhn14-26": "Mas el Consolador, el Esp\u{ed}ritu Santo, al cual el Padre enviar\u{e1} en mi nombre, \u{e9}l os ense\u{f1}ar\u{e1} todas las cosas, y os recordar\u{e1} todas las cosas que os he dicho.",
  "hs-jhn16-13": "Pero cuando viniere aquel Esp\u{ed}ritu de verdad, \u{e9}l os guiar\u{e1} \u{e1} toda verdad; porque no hablar\u{e1} de s\u{ed} mismo, sino que hablar\u{e1} todo lo que oyere, y os har\u{e1} saber las cosas que han de venir.",
  "hs-act1-8": "Mas recibir\u{e9}is la virtud del Esp\u{ed}ritu Santo que vendr\u{e1} sobre vosotros; y me sere\u{ed}s testigos en Jerusalem, y en toda Judea, y Samaria, y hasta lo \u{fa}ltimo de la tierra.",
  "hs-rom8-26": "Y asimismo tambi\u{e9}n el Esp\u{ed}ritu ayuda nuestra flaqueza: porque qu\u{e9} hemos de pedir como conviene, no lo sabemos; sino que el mismo Esp\u{ed}ritu pide por nosotros con gemidos indecibles.",
  "hs-rom8-14": "Porque todos los que son guiados por el Esp\u{ed}ritu de Dios, los tales son hijos de Dios.",
  "hs-rom8-16": "Porque el mismo Esp\u{ed}ritu da testimonio \u{e1} nuestro esp\u{ed}ritu que somos hijos de Dios.",
  "hs-eph1-13": "En el cual esperasteis tambi\u{e9}n vosotros en oyendo la palabra de verdad, el evangelio de vuestra salud: en el cual tambi\u{e9}n desde que cre\u{ed}steis, fuisteis sellados con el Esp\u{ed}ritu Santo de la promesa,",
  "hs-eph4-30": "Y no contrist\u{e9}is al Esp\u{ed}ritu Santo de Dios, con el cual est\u{e1}is sellados para el d\u{ed}a de la redenci\u{f3}n.",
  "hs-1co2-12": "Y nosotros hemos recibido, no el esp\u{ed}ritu del mundo, sino el Esp\u{ed}ritu que es de Dios, para que conozcamos lo que Dios nos ha dado;",
  "hs-eze36-27": "Y pondr\u{e9} dentro de vosotros mi esp\u{ed}ritu, y har\u{e9} que and\u{e9}is en mis mandamientos, y guard\u{e9}is mis derechos, y los pong\u{e1}is por obra.",
  "hs-zec4-6": "Entonces respondi\u{f3} y habl\u{f3}me, diciendo: Esta es palabra de Jehov\u{e1} \u{e1} Zorobabel, en que se dice: No con ej\u{e9}rcito, ni con fuerza, sino con mi esp\u{ed}ritu, ha dicho Jehov\u{e1} de los ej\u{e9}rcitos.",
  "hs-luk11-13": "Pues si vosotros, siendo malos, sab\u{e9}is dar buenas d\u{e1}divas \u{e1} vuestros hijos, \u{bf}cu\u{e1}nto m\u{e1}s vuestro Padre celestial dar\u{e1} el Esp\u{ed}ritu Santo \u{e1} los que lo pidieren de \u{e9}l?",
  "hs-2co3-17": "Porque el Se\u{f1}or es el Esp\u{ed}ritu; y donde hay el Esp\u{ed}ritu del Se\u{f1}or, all\u{ed} hay libertad.",
  "pur-jer1-5": "Antes que te formase en el vientre te conoc\u{ed}, y antes que salieses de la matriz te santifiqu\u{e9}, te d\u{ed} por profeta \u{e1} las gentes.",
  "pur-pro19-21": "Muchos pensamientos hay en el coraz\u{f3}n del hombre; mas el consejo de Jehov\u{e1} permanecer\u{e1}.",
  "pur-eph4-1": "YO pues, preso en el Se\u{f1}or, os ruego que and\u{e9}is como es digno de la vocaci\u{f3}n con que sois llamados;",
  "pur-2ti1-9": "Que nos salv\u{f3} y llam\u{f3} con vocaci\u{f3}n santa, no conforme \u{e1} nuestras obras, mas seg\u{fa}n el intento suyo y gracia, la cual nos es dada en Cristo Jes\u{fa}s antes de los tiempos de los siglos,",
  "pur-mat28-19": "Por tanto, id, y doctrinad \u{e1} todos los Gentiles, bautiz\u{e1}ndolos en el nombre del Padre, y del Hijo, y del Esp\u{ed}ritu Santo:",
  "pur-mat5-14": "Vosotros sois la luz del mundo: una ciudad asentada sobre un monte no se puede esconder.",
  "pur-est4-14": "Porque si absolutamente callares en este tiempo, respiro y libertaci\u{f3}n tendr\u{e1}n los Jud\u{ed}os de otra parte; mas t\u{fa} y la casa de tu padre perecer\u{e9}is. \u{bf}Y qui\u{e9}n sabe si para esta hora te han hecho llegar al reino?",
  "pur-1pe2-9": "Mas vosotros sois linaje escogido, real sacerdocio, gente santa, pueblo adquirido, para que anunci\u{e9}is las virtudes de aquel que os ha llamado de las tinieblas \u{e1} su luz admirable:",
  "pur-1pe4-10": "Cada uno seg\u{fa}n el don que ha recibido, admin\u{ed}strelo \u{e1} los otros, como buenos dispensadores de las diferentes gracias de Dios.",
  "pur-php3-14": "Prosigo al blanco, al premio de la soberana vocaci\u{f3}n de Dios en Cristo Jes\u{fa}s.",
  "pur-isa6-8": "Despu\u{e9}s o\u{ed} la voz del Se\u{f1}or, que dec\u{ed}a: \u{bf}A qui\u{e9}n enviar\u{e9}, y qui\u{e9}n nos ir\u{e1}? Entonces respond\u{ed} yo: Heme aqu\u{ed}, env\u{ed}ame \u{e1} m\u{ed}.",
  "pur-mic6-8": "Oh hombre, \u{e9}l te ha declarado qu\u{e9} sea lo bueno, y qu\u{e9} pida de ti Jehov\u{e1}: solamente hacer juicio, y amar misericordia, y humillarte para andar con tu Dios.",
  "pur-ecc3-1": "PARA todas las cosas hay saz\u{f3}n, y todo lo que se quiere debajo del cielo, tiene su tiempo:",
  "pur-col1-16": "Porque por \u{e9}l fueron criadas todas las cosas que est\u{e1}n en los cielos, y que est\u{e1}n en la tierra, visibles \u{e9} invisibles; sean tronos, sean dominios, sean principados, sean potestades; todo fu\u{e9} criado por \u{e9}l y para \u{e9}l.",
  "wrk-col3-23": "Y todo lo que hag\u{e1}is, hacedlo de \u{e1}nimo, como al Se\u{f1}or, y no \u{e1} los hombres;",
  "wrk-pro14-23": "En toda labor hay fruto: mas la palabra de los labios solamente empobrece.",
  "wrk-pro6-6": "Ve \u{e1} la hormiga, oh perezoso, mira sus caminos, y s\u{e9} sabio;",
  "wrk-pro10-4": "La mano negligente hace pobre: mas la mano de los diligentes enriquece.",
  "wrk-pro22-29": "\u{bf}Has visto hombre sol\u{ed}cito en su obra? delante de los reyes estar\u{e1}; no estar\u{e1} delante de los de baja suerte.",
  "wrk-2th3-10": "Porque aun estando con vosotros, os denunci\u{e1}bamos esto: Que si alguno no quisiere trabajar, tampoco coma.",
  "wrk-ecc9-10": "Todo lo que te viniere \u{e1} la mano para hacer, hazlo seg\u{fa}n tus fuerzas; porque en el sepulcro, adonde t\u{fa} vas, no hay obra, ni industria, ni ciencia, ni sabidur\u{ed}a.",
  "wrk-gen2-15": "Tom\u{f3}, pues, Jehov\u{e1} Dios al hombre, y le puso en el huerto de Ed\u{e9}n, para que lo labrara y lo guardase.",
  "wrk-1co15-58": "As\u{ed} que, hermanos m\u{ed}os amados, estad firmes y constantes, creciendo en la obra del Se\u{f1}or siempre, sabiendo que vuestro trabajo en el Se\u{f1}or no es vano.",
  "wrk-pro13-4": "Desea, y nada alcanza el alma del perezoso: mas el alma de los diligentes ser\u{e1} engordada.",
  "wrk-psa90-17": "Y sea la luz de Jehov\u{e1} nuestro Dios sobre nosotros: y ordena en nosotros la obra de nuestras manos, la obra de nuestras manos confirma.",
  "wrk-eph4-28": "El que hurtaba, no hurte m\u{e1}s; antes trabaje, obrando con sus manos lo que es bueno, para que tenga de qu\u{e9} dar al que padeciere necesidad.",
  "wrk-1th4-11": "Y que procur\u{e9}is tener quietud, y hacer vuestros negocios, y obr\u{e9}is de vuestras manos de la manera que os hemos mandado;",
  "wrk-pro21-5": "Los pensamientos del sol\u{ed}cito ciertamente van \u{e1} abundancia; mas todo presuroso, indefectiblemente \u{e1} pobreza.",
  "pure-psa119-9": "\u{bf}Con qu\u{e9} limpiar\u{e1} el joven su camino? Con guardar tu palabra.",
  "pure-psa119-11": "En mi coraz\u{f3}n he guardado tus dichos, para no pecar contra ti.",
  "pure-jas1-12": "Bienaventurado el var\u{f3}n que sufre la tentaci\u{f3}n; porque cuando fuere probado, recibir\u{e1} la corona de vida, que Dios ha prometido \u{e1} los que le aman.",
  "pure-jas1-14": "Sino que cada uno es tentado, cuando de su propia concupiscencia es atra\u{ed}do, y cebado.",
  "pure-jas4-7": "Someteos pues \u{e1} Dios; resistid al diablo, y de vosotros huir\u{e1}.",
  "pure-1co6-18": "Huid la fornicaci\u{f3}n. Cualquier otro pecado que el hombre hiciere, fuera del cuerpo es; mas el que fornica, contra su propio cuerpo peca.",
  "pure-2ti2-22": "Huye tambi\u{e9}n los deseos juveniles; y sigue la justicia, la fe, la caridad, la paz, con los que invocan al Se\u{f1}or de puro coraz\u{f3}n.",
  "pure-heb4-15": "Porque no tenemos un Pont\u{ed}fice que no se pueda compadecer de nuestras flaquezas; mas tentado en todo seg\u{fa}n nuestra semejanza, pero sin pecado.",
  "pure-mat26-41": "Velad y orad, para que no entr\u{e9}is en tentaci\u{f3}n: el esp\u{ed}ritu \u{e1} la verdad est\u{e1} presto, mas la carne enferma.",
  "pure-psa51-10": "Crea en m\u{ed}, oh Dios, un coraz\u{f3}n limpio; y renueva un esp\u{ed}ritu recto dentro de m\u{ed}.",
  "pure-1th4-3": "Porque la voluntad de Dios es vuestra santificaci\u{f3}n: que os apart\u{e9}is de fornicaci\u{f3}n;",
  "pure-job31-1": "HICE pacto con mis ojos: \u{bf}c\u{f3}mo pues hab\u{ed}a yo de pensar en virgen?",
  "pure-1jn2-16": "Porque todo lo que hay en el mundo, la concupiscencia de la carne, y la concupiscencia de los ojos, y la soberbia de la vida, no es del Padre, mas es del mundo.",
  "pure-heb2-18": "Porque en cuanto \u{e9}l mismo padeci\u{f3} siendo tentado, es poderoso para socorrer \u{e1} los que son tentados.",
  "hum-jas4-6": "Mas \u{e9}l da mayor gracia. Por esto dice: Dios resiste \u{e1} los soberbios, y da gracia \u{e1} los humildes.",
  "hum-jas4-10": "Humillaos delante del Se\u{f1}or, y \u{e9}l os ensalzar\u{e1}.",
  "hum-1pe5-5": "Igualmente, mancebos, sed sujetos \u{e1} los ancianos; y todos sumisos unos \u{e1} otros, revest\u{ed}os de humildad; porque Dios resiste \u{e1} los soberbios, y da gracia \u{e1} los humildes.",
  "hum-php2-3": "Nada hag\u{e1}is por contienda \u{f3} por vanagloria; antes bien en humildad, estim\u{e1}ndoos inferiores los unos \u{e1} los otros:",
  "hum-php2-4": "No mirando cada uno \u{e1} lo suyo propio, sino cada cual tambi\u{e9}n \u{e1} lo de los otros.",
  "hum-pro11-2": "Cuando viene la soberbia, viene tambi\u{e9}n la deshonra: mas con los humildes es la sabidur\u{ed}a.",
  "hum-pro16-18": "Antes del quebrantamiento es la soberbia; y antes de la ca\u{ed}da la altivez de esp\u{ed}ritu.",
  "hum-pro22-4": "Riquezas, y honra, y vida, son la remuneraci\u{f3}n de la humildad y del temor de Jehov\u{e1}.",
  "hum-mat23-12": "Porque el que se ensalzare, ser\u{e1} humillado; y el que se humillare, ser\u{e1} ensalzado.",
  "hum-rom12-3": "Digo pues por la gracia que me es dada, \u{e1} cada cual que est\u{e1} entre vosotros, que no tenga m\u{e1}s alto concepto de s\u{ed} que el que debe tener, sino que piense de s\u{ed} con templanza, conforme \u{e1} la medida de fe que Dios reparti\u{f3} \u{e1} cada uno.",
  "hum-isa57-15": "Porque as\u{ed} dijo el Alto y Sublime, el que habita la eternidad, y cuyo nombre es el Santo: Yo habito en la altura y la santidad, y con el quebrantado y humilde de esp\u{ed}ritu, para hacer vivir el esp\u{ed}ritu de los humildes, y para vivificar el coraz\u{f3}n de los quebrantados.",
  "hum-psa25-9": "Encaminar\u{e1} \u{e1} los humildes por el juicio, y ense\u{f1}ar\u{e1} \u{e1} los mansos su carrera.",
  "hum-jhn13-14": "Pues si yo, el Se\u{f1}or y el Maestro, he lavado vuestros pies, vosotros tambi\u{e9}n deb\u{e9}is lavar los pies los unos \u{e1} los otros.",
  "hum-2ch7-14": "Si se humillare mi pueblo, sobre los cuales ni nombre es invocado, y oraren, y buscaren mi rostro, y se convirtieren de sus malos caminos; entonces yo oir\u{e9} desde los cielos, y perdonar\u{e9} sus pecados, y sanar\u{e9} su tierra.",
};
